entries[260799] = { ["name"] = "SAF-T Bell", ["text"] = "Crafting Reagent\n\"Do you know where your Sheep is?! SAF-T Knows.\"\nSell Price:" }
entries[260800] = { ["name"] = "Shafety Sheep", ["text"] = "Use: Summons an Explosive Sheep which will charge at a nearby enemy and explode for 135 to 165 damage. Lasts for 3 min or until it explodes. (1 Min Cooldown)\n\"Guaranteed to blow up only where it's SAF!\"\nSell Price:" }
entries[260801] = { ["name"] = "EZ-Thro Fireproof Fuse", ["text"] = "Crafting Reagent\n\"Guaranteed not to burn!\"\nSell Price:" }
entries[260802] = { ["name"] = "EZ-Thro Bronze Mortar", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\nUse: Inflicts 85 to 115 Fire damage and stuns targets in a 5 yd radius for 2 sec. Any damage will break the effect. (10 Min Cooldown)\n8 Charges\n\"Thro mo mo tar!\"\nSell Price:" }
entries[260803] = { ["name"] = "EZ-Thro Grenade", ["text"] = "Use: Inflicts 213 to 287 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"Who needs safety when it's this easy to throw?\"\nSell Price:" }
entries[260804] = { ["name"] = "SAF-T Casing", ["text"] = "Crafting Reagent\n\"Extra padding for SAF-T!\"\nSell Price:" }
entries[260805] = { ["name"] = "SAF-T Bomb", ["text"] = "Use: Inflicts 149 to 201 Fire damage and stuns targets in a 5 yd radius for 3 sec. Any damage will break the effect. (1 Min Cooldown)\n\"S. A. F. T. B. O. M. B. SAF-T. Bomb.\"\nSell Price:" }
entries[260806] = { ["name"] = "Emergency Field Cloak", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nUse: Gives invisibility for 10 sec. (1 Hour Cooldown)\n3 Charges\n\"SAF-T means not getting caught.\"\nSell Price:" }
entries[260807] = { ["name"] = "Compact Critter Carrier", ["text"] = "Classes: Hunter\nRequires Level 40\n\nUse: Place a Compact Critter Carrier for 3 min that allows Hunters in your group to access their stabled pets. (30 Min Cooldown)\nSell Price:" }
entries[260808] = { ["name"] = "EZ-Thro Tru-Trigger", ["text"] = "Crafting Reagent\n\"EZ to use and almost never misfires!\"\nSell Price:" }
entries[260809] = { ["name"] = "Tru-Trigger Frag Bomb", ["text"] = "Use: Inflicts 149 to 201 Fire damage and stuns targets in an 8 yd radius for 2 sec. Any damage will break the effect. (1 Min Cooldown)\n\"Tru-Trigger frags enemies, not in your hands.\"\nSell Price:" }
entries[260810] = { ["name"] = "SAF-T Disposable Parachute", ["text"] = "Binds when equipped\nBack\n31 Armor\nUse: Reduces your fall speed for 10 sec. (30 Min Cooldown)\n3 Charges\n\"SAF-T in case you need to jump.\"\nSell Price:" }
entries[260811] = { ["name"] = "Gnomish Army Knife", ["text"] = "Requires Level 45\n\"It's got everything: a spanner, a wrench, a hammer... even a mining pick.\"\nSell Price:" }
entries[260812] = { ["name"] = "Loot-A-Rang", ["text"] = "Binds when used\nRequires Level 50\nRequires Engineering (250)\n\nUse: Retrieves the loot from a nearby corpse. (3 Sec Cooldown)\nSell Price:" }
entries[260813] = { ["name"] = "SAF-T Tube", ["text"] = "Crafting Reagent\n\"Prevents accidental oxygen exposure. That wouldn't be SAF.\"\nSell Price:" }
entries[260814] = { ["name"] = "SAF-T Clever Dynamite", ["text"] = "Use: Inflicts 340 to 460 Fire damage in a 5 yd radius. (1 Min Cooldown)\n\"SAF-T isn't dense. It's clever!\"\nSell Price:" }
entries[260815] = { ["name"] = "EZ-Thro Shell", ["text"] = "Crafting Reagent\n\"Encase your explosives in EZ to Thro thorium-plated shells.\"\nSell Price:" }
entries[260816] = { ["name"] = "EZ-Thro Thorium Grenade", ["text"] = "Use: Inflicts 300 to 500 Fire damage and stuns targets for 3 sec in a 3 yd radius. Any damage will break the effect. (1 Min Cooldown)\n\"Anyone can use grenades with EZ-Thro!\"\nSell Price:" }
entries[260817] = { ["name"] = "EZ-Thro Dark Bomb", ["text"] = "Use: Inflicts 225 to 675 Fire damage and stuns targets in a 5 yd radius for 4 sec. Any damage will break the effect. (1 Min Cooldown)\n\"So EZ, you can Thro it in the dark.\"\nSell Price:" }
entries[260818] = { ["name"] = "EZ-Thro Mana Bomb", ["text"] = "Use: Burns 675 to 1125 mana from those in the blast radius and deals 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)\nSell Price:" }
entries[260819] = { ["name"] = "EZ-Thro Field Transporter: Gadgetzan", ["text"] = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 55\nUse: Safely transport yourself to Gadgetzan in Tanaris! Emphasis on Safe! Yup, nothing bad could ever happen while using this device! (4 Hrs Cooldown)\n3 Charges\nSell Price:" }
entries[260820] = { ["name"] = "SAF-T Emergency Ripper: Everlook", ["text"] = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 55\nUse: Rips the dimensional walls asunder and transports you to Everlook in Winterspring. There are technical problems that sometimes occur, but that's what Goblin Engineering is all about! (4 Hrs Cooldown)\n3 Charges\nSell Price:" }
entries[260821] = { ["name"] = "EZ and SAF Field Transporter: Mt. Hyjal", ["text"] = "Binds when used\nUnique-Equipped\nTrinket\nRequires Level 60\nUse: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n3 Charges\n\"Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?\"\nSell Price:" }
entries[260822] = { ["name"] = "Ultrasafe Rechargeable Battery", ["text"] = "Requires Level 60\n\nUse: Restores 3 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives. (1 Min Cooldown)\nSell Price:" }
entries[260823] = { ["name"] = "Dimensional Transporter - Mt. Hyjal", ["text"] = "Binds when used\nRequires Level 60\nRequires Engineering (300)\n\nUse: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering. (4 Hrs Cooldown)\n\"A dangerous amalgamation of Goblin and Gnome engineering techniques.\"\nSell Price:" }
entries[260824] = { ["name"] = "Gnomish Poultryizer", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nRequires Level 60\nUse: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)\nSell Price:" }
entries[260825] = { ["name"] = "Ultralight Goblin Glider", ["text"] = "Binds when used\nRequires Engineering (250)\n\nUse: Glide downward through the air for 10 sec while controlling your direction of travel. (3 Min Cooldown)" }
entries[260826] = { ["name"] = "Gnomish Weather Machine NYI", ["text"] = "Binds when used\nRequires Level 60\nRequires Engineering (300)\nSell Price:" }
entries[260827] = { ["name"] = "Stealthman 52", ["text"] = "Requires Level 55\nRequires Engineering (250)\n\nUse: Cloaks the user in a stealth field for up to 1 min. Cannot be used in combat. The field lasts for up to 6 sec after moving. (5 Min Cooldown)\n\"Used by real secret agents.\"\nSell Price:" }
entries[260828] = { ["name"] = "SAF-T Nitro Boosts", ["text"] = "Binds when equipped\nWaist\nRequires Level 55\nUse: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.\n3 Charges\n\"Rocket to safety with SAF-T.\"\nSell Price:" }
entries[260829] = { ["name"] = "EZ-Thro Magnetic Displacer", ["text"] = "Binds when equipped\nWaist\nRequires Level 55\nUse: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\n\nCan only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.\n3 Charges\n\"EZ-Thro corporation not responsible for magnets preventing grenades from being thrown.\"\nSell Price:" }
entries[260830] = { ["name"] = "SAF-T Teleport", ["text"] = "Binds when equipped\nWaist\nRequires Level 55\nUse: Teleport forward 20 yds.\n3 Charges\n\"Teleport to SAF-T!\"\nSell Price:" }
entries[260880] = { ["name"] = "Air Construct Core", ["text"] = "Quest Item\nUnique\n\"The glowing orb seems to be looking at you, following your movements with quiet curiosity.\"" }
entries[260881] = { ["name"] = "Crystallized Lightning", ["text"] = "Quest Item\nUnique\n\"The surface of this object is smooth to the touch and makes the hair on the back of your neck stand up when you hold it.\"" }
entries[260883] = { ["name"] = "Enchanted Gyrozephyr", ["text"] = "Quest Item\nUnique\n\"This object softly vibrates, constantly in a state of perpetual motion. If you try to hold it still, the force it exerts increases greatly in intensity.\"" }
